import { getJson } from '../../api/http';
import { claimsKey } from '../claims/claimsQuery';

/** A void reason on the sheet, and how many VOID claims were voided with it. */
export type VoidReason = { reason: string; voided: number };

/** Under the claims' key, so a claim's change (a void) re-reads the counts, and re-loading the sheet re-reads the list. */
export const voidReasonsKey = (sheetId: string) => [...claimsKey(sheetId), 'void-reasons'] as const;

export const voidReasonsQuery = (sheetId: string) => ({
  queryKey: voidReasonsKey(sheetId),
  queryFn: () => getJson<VoidReason[]>(`/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { voidReasonsKey, voidReasonsQuery } from './voidReasonsQuery';
import type { VoidReason } from './voidReasonsQuery';

/** The sheet's void reasons, and the entry a reason is added through. While the list is not empty, a claim is voided
 *  only with a reason chosen from it. A blank reason, or one already on the list, is refused. */
function VoidReasons({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const reasons = useQuery(voidReasonsQuery(sheetId));
  const [text, setText] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: { reason: string }) =>
      postJson<VoidReason>(`/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheetId) });
      setText('');
    },
    onError: (e: Error) => setError(e.message || 'The void reason could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once(() => save.mutateAsync({ reason: text.trim() }));
  };

  return (
    <section data-testid="void-reasons">
      <h3>Void reasons</h3>
      <form onSubmit={submit}>
        <label>
          Reason{' '}
          <input
            data-testid="void-reason-text"
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="void-reason-add" disabled={save.isPending}>
          Add void reason
        </button>
        {error && <p data-testid="void-reason-error">{error}</p>}
      </form>
      {reasons.isError && <p data-testid="void-reasons-load-error">Could not load the void reasons.</p>}
      <ul data-testid="void-reasons-list">
        {(reasons.data ?? []).map((r) => (
          <li key={r.reason} data-testid={`void-reason-row-${r.reason}`}>
            {r.reason}
          </li>
        ))}
      </ul>
    </section>
  );
}

// Keyed by sheet, so a typed value or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 6.6,
  Component: ({ sheetId }) => <VoidReasons key={`void-reasons-${sheetId}`} sheetId={sheetId} />,
});
-- The sheet's void reasons, listed in the order they were added; each reason at most once per sheet, without regard to
-- case. While a sheet has any, a claim is voided only with one of them, kept on the claim (null: voided without one, or
-- not voided). Kept in history too (see V39 and V40); the claim's journal trigger is made again around the change, as
-- in V41.
CREATE TABLE void_reason (
    sheet_id VARCHAR(255) NOT NULL,
    reason VARCHAR(255) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);
CREATE TABLE void_reason_history AS SELECT * FROM void_reason;
ALTER TABLE void_reason_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE void_reason_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE void_reason_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX void_reason_history_key ON void_reason_history (sheet_id, reason);
CREATE TRIGGER void_reason_journal AFTER INSERT, UPDATE, DELETE ON void_reason FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN void_reason VARCHAR(255);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- A person's flag, set by a steward: a reason, in force while the sheet's today is on or before its until-date. While in
-- force, only a steward may open the person's claims. One flag per person: flagging again replaces it. Kept by person id
-- without a reference, so a person leaving the sheet (merged, transferred) leaves only an unread row behind.
CREATE TABLE person_flag (
    person_id  BIGINT       NOT NULL PRIMARY KEY,
    reason     VARCHAR(255) NOT NULL,
    until_date DATE         NOT NULL
);

